INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-15-z0-q0','nism-15-z0','Under SEBI (Research Analysts) Regulations 2014, what is the mandatory holding restriction on research analysts regarding securities they recommend?','["They cannot trade in that security for 30 days before and 5 days after issuing the research report","They cannot trade contrary to their recommendation for 30 days after publishing the research report","They can trade anytime provided they notify their compliance officer within 48 hours","There are no restrictions on personal trading"]',1,'SEBI mandates a 30-day blackout period following report publication during which the analyst cannot execute personal trades contrary to their published recommendation.',0) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-15-z0-q1','nism-15-z0','In Discounted Cash Flow (DCF) valuation, Free Cash Flow to Firm (FCFF) should be discounted at which rate of return?','["Cost of Equity (Ke) calculated using CAPM","Weighted Average Cost of Capital (WACC)","Pre-tax Cost of Debt (Kd)","Risk-Free Rate of Government Securities"]',1,'Because FCFF represents cash flows available to both equity and debt providers, it must be discounted using the Weighted Average Cost of Capital (WACC).',1) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-15-z0-q2','nism-15-z0','What is the formula for calculating Enterprise Value (EV)?','["Market Capitalization + Total Debt - Cash and Cash Equivalents","Total Assets - Total Liabilities","EBITDA * Price to Earnings Ratio","Net Profit * Shareholder Equity"]',0,'Enterprise Value = Market Capitalization + Total Debt + Minority Interest + Preferred Shares - Total Cash and Cash Equivalents.',2) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-15-z0-q3','nism-15-z0','Which financial ratio best measures a company''s ability to service its debt obligations from operational earnings before depreciation and amortization?','["Current Ratio","Interest Coverage Ratio (EBITDA / Interest Expense)","Price to Book Value (P/B)","Asset Turnover Ratio"]',1,'The Interest Coverage Ratio (EBITDA / Interest) measures how many times the company can pay its current interest obligations with its operating earnings.',3) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-15-z0-q4','nism-15-z0','What does the Beneish M-Score calculate in forensic accounting analysis?','["Default probability within 12 months","The likelihood that a company is manipulating its financial earnings","Optimal capital structure leverage","Terminal growth rate in perpetual DCF"]',1,'The Beneish M-Score uses 8 financial ratios to identify whether a company has manipulated or falsified its reported accounting earnings.',4) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
